import{_ as e,o as r,c as t,a3 as n}from"./chunks/framework.Cj_fzHAr.js";const p=JSON.parse('{"title":"Firmas digitales y DS 44","description":"","frontmatter":{},"headers":[],"relativePath":"ds44/firmas-digitales.md","filePath":"ds44/firmas-digitales.md"}'),i={name:"ds44/firmas-digitales.md"};function s(o,a,d,l,c,u){return r(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="firmas-digitales-y-ds-44" tabindex="-1">Firmas digitales y DS 44 <a class="header-anchor" href="#firmas-digitales-y-ds-44" aria-label="Permalink to &quot;Firmas digitales y DS 44&quot;">​</a></h1><p>El DS 44 exige que los registros de seguridad estén <strong>firmados y disponibles</strong> ante una fiscalización. La plataforma digitaliza la firma manteniendo, por cada acto firmado, una <strong>evidencia verificable</strong>: quién firmó, cuándo y desde dónde.</p><div class="warning custom-block"><p class="custom-block-title">Consulta legal pendiente</p><p>La <strong>validez jurídica del PIN como firma electrónica</strong> ante un fiscalizador del DS 44 está siendo evaluada con la Dirección del Trabajo. La funcionalidad opera con normalidad y deja trazabilidad completa, pero <strong>por ahora no debe usarse como única prueba legal</strong> hasta tener la respuesta oficial.</p></div><h2 id="formas-de-firmar" tabindex="-1">Formas de firmar <a class="header-anchor" href="#formas-de-firmar" aria-label="Permalink to &quot;Formas de firmar&quot;">​</a></h2><p>La plataforma ofrece distintas formas de firmar según la situación:</p><table tabindex="0"><thead><tr><th>Forma</th><th>¿Cuándo se usa?</th></tr></thead><tbody><tr><td><strong>PIN</strong></td><td>Firma estándar: la persona confirma con su PIN personal de 4 dígitos.</td></tr><tr><td><strong>Offline</strong></td><td>Firma en terreno <strong>sin conexión</strong>, que se sincroniza al recuperar la red.</td></tr><tr><td><strong>Presencial</strong></td><td>Firma asistida ante un relator o supervisor presente.</td></tr></tbody></table><h2 id="un-registro-que-no-se-altera" tabindex="-1">Un registro que no se altera <a class="header-anchor" href="#un-registro-que-no-se-altera" aria-label="Permalink to &quot;Un registro que no se altera&quot;">​</a></h2><p>Cada firma queda guardada como un <strong>registro que no se modifica ni se elimina</strong>. Por cada firma se conserva, entre otros datos:</p><ul><li><strong>Quién firmó</strong> (nombre y RUT).</li><li><strong>Qué firmó</strong> (el documento o la actividad).</li><li><strong>Fecha y hora</strong> exactas.</li><li><strong>Desde dónde</strong> se firmó.</li><li>Un <strong>código de verificación</strong> que permite comprobar la autenticidad.</li></ul><blockquote><p>🔒 Esta combinación de <strong>PIN + fecha/hora + verificación</strong> es la evidencia que la plataforma conserva por cada firma, y es lo que da respaldo al cumplimiento.</p></blockquote><h2 id="firma-sin-conexion-en-terreno" tabindex="-1">Firma sin conexión en terreno <a class="header-anchor" href="#firma-sin-conexion-en-terreno" aria-label="Permalink to &quot;Firma sin conexión en terreno&quot;">​</a></h2><p>Como muchas obras tienen mala señal, la firma puede capturarse <strong>sin internet</strong> y sincronizarse después:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. La persona firma en el celular o tablet, sin conexión</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. La firma se guarda de forma segura en el dispositivo</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. Al recuperar la señal, se sincroniza automáticamente con el sistema</span></span></code></pre></div><p>Cómo usarlo en el día a día, en el módulo de <a href="/manual/modulos/firmas.html">Firmas Digitales</a>.</p><h2 id="quien-firma-segun-el-documento" tabindex="-1">Quién firma según el documento <a class="header-anchor" href="#quien-firma-segun-el-documento" aria-label="Permalink to &quot;Quién firma según el documento&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situación</th><th>Quién firma</th></tr></thead><tbody><tr><td>Documento de obra (DS 44)</td><td>Prevencionista y/o Trabajador, según el documento</td></tr><tr><td>Entrega de EPP</td><td>Trabajador + Supervisor</td></tr><tr><td>Capacitación SST</td><td>Asistentes + Relator</td></tr><tr><td>Documento diario asignado</td><td>La persona asignada</td></tr></tbody></table><h2 id="estado-de-una-firma" tabindex="-1">Estado de una firma <a class="header-anchor" href="#estado-de-una-firma" aria-label="Permalink to &quot;Estado de una firma&quot;">​</a></h2><p>Una firma normalmente está <strong>Válida</strong> (es la evidencia activa de cumplimiento). Si su autenticidad se cuestiona, puede quedar marcada como <strong>Disputada</strong>, y si se invalida formalmente, como <strong>Anulada</strong>. En todos los casos el registro original <strong>se conserva</strong>, para no perder la trazabilidad que exige el DS 44.</p><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>¿El PIN tiene validez legal?</strong> Su validez ante un fiscalizador está en evaluación (ver el aviso arriba). La firma funciona y deja trazabilidad completa, pero por ahora no debe ser la única prueba legal.</p><p><strong>¿Puedo firmar sin internet?</strong> Sí. Usa la firma <strong>offline</strong>: se guarda en tu dispositivo y se sincroniza sola cuando vuelvas a tener señal.</p><p><strong>Una firma quedó como &quot;disputada&quot;. ¿Se borró la original?</strong> No. El registro original se conserva siempre. Los estados &quot;disputada&quot; o &quot;anulada&quot; solo dejan constancia de la controversia, sin eliminar la evidencia.</p>`,22)])])}const g=e(i,[["render",s]]);export{p as __pageData,g as default};
